INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_rule_32086', '南岭省公务员招录资格复审材料要求', '复审材料规则', '临溪县人社局考录科', '2024-05-23', '现行有效', '复审时应提交本人身份证、毕业证书、学位证书、学信网教育部学历证书电子注册备案表原件及复印件。……共 5 条。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_rule_07146', '云台区公务员招录资格复审材料要求', '复审材料规则', '云台区人力资源和社会保障局', '2025-07-21', '已修订', '复审时应提交本人身份证、毕业证书、学位证书、学信网教育部学历证书电子注册备案表原件及复印件。……详见正文各条。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_rule_19572', '南岭省公务员招录报考专业认定办法', '专业认定办法', '南岭市考试中心', '2026-10-17', '现行有效', '岗位专业要求以招录公告和专业目录为准，考生对专业是否符合有疑问的，应向招录单位书面咨询。……与往年相比新增两项要求。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_rule_94030', '南岭省公务员招录考试诚信与违纪处理', '诚信处理规则', '南岭市考试中心', '2026-07-21', '已修订', '购买、出售、传播涉及考试内容或考生名单的信息，按违纪处理并取消当次考试资格。……与往年相比调整了适用范围。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_rule_59478', '南岭省公务员招录面试确认与放弃处理', '面试确认规则', '云台区人力资源和社会保障局', '2026-03-12', '现行有效', '进入面试的考生须在公告规定期限内本人完成确认，逾期未确认的视为自动放弃。……共 4 条。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_rule_34538', '云台区公务员招录面试确认与放弃处理', '面试确认规则', '云台区人力资源和社会保障局', '2026-09-13', '现行有效', '进入面试的考生须在公告规定期限内本人完成确认，逾期未确认的视为自动放弃。……与往年相比调整了适用范围。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_rule_78623', '南岭省公务员招录个人信息保护要求', '信息保护规则', '南岭省公务员局考试录用处', '2025-10-03', '现行有效', '招录过程中收集的个人信息仅用于资格审核、考务组织和聘用管理，不得用于其他用途。……与往年相比新增两项要求。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_ann_南岭_2023_450', '南岭省 2023 年度公务员招录公告（第二批）', '2023 招录公告', '南岭省人事考试院', '2023-04-10', '已废止', '南岭省 2023 年度计划招录 1073 人，其中综合管理类 428 人，报名时间为 5 月 24 日起共 9 天。');
