INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_dept_891145', '南岭省考试收费管理规定（试行）', '考试收费管理规定', '临溪县人社局考录科', '2024-07-03', '现行有效', '笔试考务费按物价部门核定标准收取，不得以任何名义加收。……共 3 条。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_dept_978684', '南江区考试收费管理规定（试行）', '考试收费管理规定', '南岭省招录主管部门', '2024-08-09', '已修订', '笔试考务费按物价部门核定标准收取，不得以任何名义加收。……适用于南江区范围。');
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES ('stat_dept_428586', '云台区考试收费管理规定（试行）', '考试收费管理规定', '南岭省公务员局考试录用处', '2026-09-02', '现行有效', '笔试考务费按物价部门核定标准收取，不得以任何名义加收。……适用于云台区范围。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_prof_dir_b12_2026_1', 'stat_prof_dir_b12_2026', '第 1 条', 1, '类目列名', 'B12 公共管理类列名：公共事业管理、行政管理、劳动与社会保障、土地资源管理、城市管理、公共数据治理。本科层次按毕业证书载明的专业名称对照本条列名认定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_prof_dir_b12_2026_2', 'stat_prof_dir_b12_2026', '第 2 条', 2, '认定口径', '考生所学专业名称与本类目列名一致的，视为符合本类目岗位的专业要求；名称不一致但考生认为培养内容相近的，应在报名前向招录单位书面咨询，由招录单位作出认定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_prof_dir_b1203_2026_1', 'stat_prof_dir_b1203_2026', '第 1 条', 1, '方向列名', 'B12-03 数据治理方向列名：数据治理、政务数据管理、数据科学与大数据技术、信息资源管理。公共数据治理未列入本方向列名。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_prof_dir_b1203_2026_2', 'stat_prof_dir_b1203_2026', '第 2 条', 2, '与上位类目的关系', '本方向为 B12 公共管理类下设方向，岗位明确要求本方向的，仅接受本方向列名；不得以属于 B12 公共管理类为由推定符合本方向要求。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_review_material_2026_1', 'stat_review_material_2026', '第 1 条', 1, '材料范围', '资格复审需提交身份证、学生证或毕业证书、成绩单、就业推荐表和学信网在线验证报告。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_review_material_2026_2', 'stat_review_material_2026', '第 2 条', 2, '本人确认', '涉及身份证明、成绩单和学信验证报告的提交与上传，须由考生本人确认后办理，不接受他人代为提交电子件。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_review_material_2026_3', 'stat_review_material_2026', '第 3 条', 3, '有效期要求', '学信网在线验证报告的有效期须覆盖资格复审当日；有效期不足的应重新申请并打印。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b12_2024_1', 'stat_dir_b12_2024', '第 1 条', 1, '类目列名', 'B12 公共管理类列名：公共事业管理、行政管理、劳动与社会保障、土地资源管理、城市管理。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b12_2024_2', 'stat_dir_b12_2024', '第 2 条', 2, '学历层次', '本类目同时适用本科与研究生层次，研究生层次另见 B12-R 分册；专科层次不适用本类目。');
