INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2024_1', 'stat_dir_b18_2024', '第 1 条', 1, '类目列名', 'B18 管理科学与工程类列名：管理科学、信息管理与信息系统、工程管理。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2024_2', 'stat_dir_b18_2024', '第 2 条', 2, '学历层次', '本类目同时适用本科与研究生层次，研究生层次另见 B18-R 分册；专科层次不适用本类目。');
