INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2025_2', 'stat_dir_b18_2025', '第 2 条', 2, '学历层次', '本类目同时适用本科与研究生层次，研究生层次另见 B18-R 分册；专科层次不适用本类目。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2025_3', 'stat_dir_b18_2025', '第 3 条', 3, '认定口径', '专业名称含方向、领域等后缀的，以学信网学历证书电子注册备案表载明为准。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2025_4', 'stat_dir_b18_2025', '第 4 条', 4, '修订说明', '相较 2024 年度版本，本次合并列名 5 个，调整原因为专业目录更新。');
