INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2026_3', 'stat_dir_b18_2026', '第 3 条', 3, '修订说明', '相较 2025 年度版本，本次合并列名 5 个，调整原因为专业目录更新。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2026_4', 'stat_dir_b18_2026', '第 4 条', 4, '学历层次', '本类目同时适用本科与研究生层次，研究生层次另见 B18-R 分册；专科层次不适用本类目。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2023_1', 'stat_dir_b18_2023', '第 1 条', 1, '类目列名', 'B18 管理科学与工程类列名：管理科学、信息管理与信息系统、工程管理。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2023_2', 'stat_dir_b18_2023', '第 2 条', 2, '认定口径', '本类目所列专业名称以教育部本科专业目录为基础，结合本省岗位实际需要确定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2023_3', 'stat_dir_b18_2023', '第 3 条', 3, '修订说明', '相较 2022 年度版本，本次合并列名 1 个，调整原因为专业目录更新。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dir_b18_2023_4', 'stat_dir_b18_2023', '第 4 条', 4, '认定口径', '同一专业名称在不同学位授予门类下的，按毕业证书载明的专业名称认定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_32086_1', 'stat_rule_32086', '第 1 条', 1, '资格复审材料', '复审时应提交本人身份证、毕业证书、学位证书、学信网教育部学历证书电子注册备案表原件及复印件。本条由临溪县人社局考录科负责解释。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_32086_2', 'stat_rule_32086', '第 2 条', 2, '资格复审材料', '应届毕业生尚未取得毕业证书的，提交学生证和学校出具的应届毕业生证明，并在规定期限内补交。执行中遇有特殊情形的，报上一级主管部门确定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_32086_3', 'stat_rule_32086', '第 3 条', 3, '资格复审材料', '在线验证报告的有效期须覆盖资格复审当日，过期的应重新申请并打印。本条与上位规定不一致的，适用上位规定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_32086_4', 'stat_rule_32086', '第 4 条', 4, '资格复审材料', '涉及身份证明和学历学位材料的提交，须由考生本人确认后办理，不接受他人代为提交电子件。本条自2026 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_32086_5', 'stat_rule_32086', '第 5 条', 5, '资格复审材料', '材料存在涂改、伪造或与登记信息不符的，取消聘用资格并记入诚信档案。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_07146_1', 'stat_rule_07146', '第 1 条', 1, '资格复审材料', '复审时应提交本人身份证、毕业证书、学位证书、学信网教育部学历证书电子注册备案表原件及复印件。执行中遇有特殊情形的，报上一级主管部门确定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_07146_2', 'stat_rule_07146', '第 2 条', 2, '资格复审材料', '应届毕业生尚未取得毕业证书的，提交学生证和学校出具的应届毕业生证明，并在规定期限内补交。本条与上位规定不一致的，适用上位规定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_07146_3', 'stat_rule_07146', '第 3 条', 3, '资格复审材料', '在线验证报告的有效期须覆盖资格复审当日，过期的应重新申请并打印。本条自2026 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_07146_4', 'stat_rule_07146', '第 4 条', 4, '资格复审材料', '涉及身份证明和学历学位材料的提交，须由考生本人确认后办理，不接受他人代为提交电子件。相关材料按档案管理规定保存不少于 3 年。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_07146_5', 'stat_rule_07146', '第 5 条', 5, '资格复审材料', '材料存在涂改、伪造或与登记信息不符的，取消聘用资格并记入诚信档案。执行中遇有特殊情形的，报上一级主管部门确定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_19572_1', 'stat_rule_19572', '第 1 条', 1, '报考专业认定', '岗位专业要求以招录公告和专业目录为准，考生对专业是否符合有疑问的，应向招录单位书面咨询。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_19572_2', 'stat_rule_19572', '第 2 条', 2, '报考专业认定', '招录单位可要求考生提供培养方案、课程成绩单等佐证材料，据以作出认定结论。本条适用于南岭省范围内的招录活动。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_19572_3', 'stat_rule_19572', '第 3 条', 3, '报考专业认定', '认定结论由招录单位作出并书面告知，任何机构或个人的口头意见不作为依据。本条适用于南岭省范围内的招录活动。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_19572_4', 'stat_rule_19572', '第 4 条', 4, '报考专业认定', '跨类目报考的，以岗位所列类目为准，不适用相近专业推定。相关材料按档案管理规定保存不少于 10 年。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_94030_1', 'stat_rule_94030', '第 1 条', 1, '考试诚信与违', '购买、出售、传播涉及考试内容或考生名单的信息，按违纪处理并取消当次考试资格。本条适用于南岭省范围内的招录活动。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_94030_2', 'stat_rule_94030', '第 2 条', 2, '考试诚信与违', '组织或参与替考、代考的，五年内不得报考公务员，构成犯罪的依法追究刑事责任。本条适用于南岭省范围内的招录活动。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_94030_3', 'stat_rule_94030', '第 3 条', 3, '考试诚信与违', '宣称掌握内部试题、内部名单或可疏通资格审核的，属虚假宣传，考生不应轻信或参与。本条自2026 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_94030_4', 'stat_rule_94030', '第 4 条', 4, '考试诚信与违', '考试机构建立诚信档案库，记录违纪违规行为及处理结果，供招录单位查询。本条与上位规定不一致的，适用上位规定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_59478_1', 'stat_rule_59478', '第 1 条', 1, '面试确认与放', '进入面试的考生须在公告规定期限内本人完成确认，逾期未确认的视为自动放弃。执行中遇有特殊情形的，报上一级主管部门确定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_59478_2', 'stat_rule_59478', '第 2 条', 2, '面试确认与放', '确认后无正当理由不参加面试的，记入诚信档案。执行中遇有特殊情形的，报上一级主管部门确定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_59478_3', 'stat_rule_59478', '第 3 条', 3, '面试确认与放', '因不可抗力无法按期确认的，应在期限内提交书面说明并附证明材料。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_59478_4', 'stat_rule_59478', '第 4 条', 4, '面试确认与放', '放弃面试产生的空缺，按笔试成绩从高到低依次递补。本条自2026 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_34538_1', 'stat_rule_34538', '第 1 条', 1, '面试确认与放', '进入面试的考生须在公告规定期限内本人完成确认，逾期未确认的视为自动放弃。本条自2026 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_34538_2', 'stat_rule_34538', '第 2 条', 2, '面试确认与放', '确认后无正当理由不参加面试的，记入诚信档案。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_34538_3', 'stat_rule_34538', '第 3 条', 3, '面试确认与放', '因不可抗力无法按期确认的，应在期限内提交书面说明并附证明材料。相关材料按档案管理规定保存不少于 10 年。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_34538_4', 'stat_rule_34538', '第 4 条', 4, '面试确认与放', '放弃面试产生的空缺，按笔试成绩从高到低依次递补。本条由云台区人力资源和社会保障局负责解释。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_78623_1', 'stat_rule_78623', '第 1 条', 1, '个人信息保护', '招录过程中收集的个人信息仅用于资格审核、考务组织和聘用管理，不得用于其他用途。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_78623_2', 'stat_rule_78623', '第 2 条', 2, '个人信息保护', '考生应通过官方系统提交材料，避免通过社交平台传输身份证、成绩单等敏感材料。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_rule_78623_3', 'stat_rule_78623', '第 3 条', 3, '个人信息保护', '任何单位和个人不得非法获取、出售或者向他人提供考生个人信息。本条与上位规定不一致的，适用上位规定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_450_1', 'stat_ann_南岭_2023_450', '第 1 条', 1, '聘用与试用期', '拟录用人员公示 5 个工作日，公示无异议的办理录用手续，试用期一年，试用期满考核不合格的取消录用。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_450_2', 'stat_ann_南岭_2023_450', '第 2 条', 2, '咨询与监督渠道', '政策咨询由招录单位负责，考务咨询由考试机构负责；监督举报电话在公告首页公布，实名举报优先受理。本条由招录主管部门负责解释。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_450_3', 'stat_ann_南岭_2023_450', '第 3 条', 3, '加分与照顾政策', '服务基层项目人员按服务年限加 3 分，加分计入笔试成绩；同一考生符合多项加分条件的，按最高项计算，不累加。执行中遇有特殊情形的，报上一级主管部门确定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_450_4', 'stat_ann_南岭_2023_450', '第 4 条', 4, '报名与资格审查', '报名采用网上填报，资格初审由招录单位在 6 个工作日内完成；初审未通过的可在报名截止前改报其他岗位，已缴费的按规定退还。具体经办科室及联系方式见南岭省官网公示栏。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_450_5', 'stat_ann_南岭_2023_450', '第 5 条', 5, '笔试科目与分值', '笔试科目为行政职业能力测验与申论，各 100 分，总成绩按笔试 50 %、面试 50 % 加权计算，保留小数点后一位。相关材料按档案管理规定保存不少于 10 年。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_889_1', 'stat_ann_南岭_2023_889', '第 1 条', 1, '加分与照顾政策', '服务基层项目人员按服务年限加 2 分，加分计入笔试成绩；同一考生符合多项加分条件的，按最高项计算，不累加。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_889_2', 'stat_ann_南岭_2023_889', '第 2 条', 2, '咨询与监督渠道', '政策咨询由招录单位负责，考务咨询由考试机构负责；监督举报电话在公告首页公布，实名举报优先受理。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_889_3', 'stat_ann_南岭_2023_889', '第 3 条', 3, '报名与资格审查', '报名采用网上填报，资格初审由招录单位在 5 个工作日内完成；初审未通过的可在报名截止前改报其他岗位，已缴费的按规定退还。本条适用于南岭市范围内的招录活动。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_889_4', 'stat_ann_南岭_2023_889', '第 4 条', 4, '聘用与试用期', '拟录用人员公示 6 个工作日，公示无异议的办理录用手续，试用期一年，试用期满考核不合格的取消录用。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2023_889_5', 'stat_ann_南岭_2023_889', '第 5 条', 5, '体检与考察', '体检按公务员录用体检通用标准执行，考察内容包括政治素质、道德品行、能力素质、遵纪守法和廉洁自律情况。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_云台_2023_621_1', 'stat_ann_云台_2023_621', '第 1 条', 1, '笔试科目与分值', '笔试科目为行政职业能力测验与申论，各 100 分，总成绩按笔试 60 %、面试 40 % 加权计算，保留小数点后一位。本条适用于云台区范围内的招录活动。');
