INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_临溪_2024_795_4', 'stat_ann_临溪_2024_795', '第 4 条', 4, '加分与照顾政策', '服务基层项目人员按服务年限加 4 分，加分计入笔试成绩；同一考生符合多项加分条件的，按最高项计算，不累加。本条与上位规定不一致的，适用上位规定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南江_2024_757_1', 'stat_ann_南江_2024_757', '第 1 条', 1, '咨询与监督渠道', '政策咨询由招录单位负责，考务咨询由考试机构负责；监督举报电话在公告首页公布，实名举报优先受理。本条自2024 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南江_2024_757_2', 'stat_ann_南江_2024_757', '第 2 条', 2, '聘用与试用期', '拟录用人员公示 6 个工作日，公示无异议的办理录用手续，试用期一年，试用期满考核不合格的取消录用。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南江_2024_757_3', 'stat_ann_南江_2024_757', '第 3 条', 3, '加分与照顾政策', '服务基层项目人员按服务年限加 4 分，加分计入笔试成绩；同一考生符合多项加分条件的，按最高项计算，不累加。本条适用于南江区范围内的招录活动。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南江_2024_757_4', 'stat_ann_南江_2024_757', '第 4 条', 4, '报名与资格审查', '报名采用网上填报，资格初审由招录单位在 2 个工作日内完成；初审未通过的可在报名截止前改报其他岗位，已缴费的按规定退还。本条适用于南江区范围内的招录活动。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南江_2024_757_5', 'stat_ann_南江_2024_757', '第 5 条', 5, '体检与考察', '体检按公务员录用体检通用标准执行，考察内容包括政治素质、道德品行、能力素质、遵纪守法和廉洁自律情况。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_砚山_2024_843_1', 'stat_ann_砚山_2024_843', '第 1 条', 1, '体检与考察', '体检按公务员录用体检通用标准执行，考察内容包括政治素质、道德品行、能力素质、遵纪守法和廉洁自律情况。本条由招录主管部门负责解释。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_砚山_2024_843_2', 'stat_ann_砚山_2024_843', '第 2 条', 2, '咨询与监督渠道', '政策咨询由招录单位负责，考务咨询由考试机构负责；监督举报电话在公告首页公布，实名举报优先受理。执行中遇有特殊情形的，报上一级主管部门确定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_砚山_2024_843_3', 'stat_ann_砚山_2024_843', '第 3 条', 3, '加分与照顾政策', '服务基层项目人员按服务年限加 4 分，加分计入笔试成绩；同一考生符合多项加分条件的，按最高项计算，不累加。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_砚山_2024_843_4', 'stat_ann_砚山_2024_843', '第 4 条', 4, '笔试科目与分值', '笔试科目为行政职业能力测验与申论，各 100 分，总成绩按笔试 50 %、面试 50 % 加权计算，保留小数点后一位。本条自2024 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南岭_2025_555_1', 'stat_ann_南岭_2025_555', '第 1 条', 1, '聘用与试用期', '拟录用人员公示 5 个工作日，公示无异议的办理录用手续，试用期一年，试用期满考核不合格的取消录用。本条与上位规定不一致的，适用上位规定。');
