INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_临溪_2026_327_1', 'stat_ann_临溪_2026_327', '第 1 条', 1, '体检与考察', '体检按公务员录用体检通用标准执行，考察内容包括政治素质、道德品行、能力素质、遵纪守法和廉洁自律情况。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_临溪_2026_327_2', 'stat_ann_临溪_2026_327', '第 2 条', 2, '笔试科目与分值', '笔试科目为行政职业能力测验与申论，各 100 分，总成绩按笔试 50 %、面试 40 % 加权计算，保留小数点后一位。本条自2026 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_临溪_2026_327_3', 'stat_ann_临溪_2026_327', '第 3 条', 3, '聘用与试用期', '拟录用人员公示 7 个工作日，公示无异议的办理录用手续，试用期一年，试用期满考核不合格的取消录用。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南江_2026_833_1', 'stat_ann_南江_2026_833', '第 1 条', 1, '聘用与试用期', '拟录用人员公示 5 个工作日，公示无异议的办理录用手续，试用期一年，试用期满考核不合格的取消录用。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南江_2026_833_2', 'stat_ann_南江_2026_833', '第 2 条', 2, '笔试科目与分值', '笔试科目为行政职业能力测验与申论，各 100 分，总成绩按笔试 60 %、面试 40 % 加权计算，保留小数点后一位。本条自2026 年度招录起施行。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_南江_2026_833_3', 'stat_ann_南江_2026_833', '第 3 条', 3, '报名与资格审查', '报名采用网上填报，资格初审由招录单位在 2 个工作日内完成；初审未通过的可在报名截止前改报其他岗位，已缴费的按规定退还。相关材料按档案管理规定保存不少于 3 年。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_砚山_2026_382_1', 'stat_ann_砚山_2026_382', '第 1 条', 1, '加分与照顾政策', '服务基层项目人员按服务年限加 3 分，加分计入笔试成绩；同一考生符合多项加分条件的，按最高项计算，不累加。具体经办科室及联系方式见砚山区官网公示栏。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_砚山_2026_382_2', 'stat_ann_砚山_2026_382', '第 2 条', 2, '笔试科目与分值', '笔试科目为行政职业能力测验与申论，各 100 分，总成绩按笔试 50 %、面试 40 % 加权计算，保留小数点后一位。本条由招录主管部门负责解释。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_砚山_2026_382_3', 'stat_ann_砚山_2026_382', '第 3 条', 3, '报名与资格审查', '报名采用网上填报，资格初审由招录单位在 7 个工作日内完成；初审未通过的可在报名截止前改报其他岗位，已缴费的按规定退还。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_ann_砚山_2026_382_4', 'stat_ann_砚山_2026_382', '第 4 条', 4, '聘用与试用期', '拟录用人员公示 6 个工作日，公示无异议的办理录用手续，试用期一年，试用期满考核不合格的取消录用。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_691456_1', 'stat_dept_691456', '第 1 条', 1, '政务服务窗口', '窗口岗位实行首问负责制，工作人员应当在受理时一次性告知所需材料。本条适用于临溪县范围内的招录活动。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_691456_2', 'stat_dept_691456', '第 2 条', 2, '政务服务窗口', '窗口岗位新录用人员上岗前须完成不少于 40 学时的业务培训并通过考核。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_691456_3', 'stat_dept_691456', '第 3 条', 3, '政务服务窗口', '服务对象评价结果纳入年度考核，连续两次评价不合格的调离窗口岗位。');
