INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_099951_1', 'stat_dept_099951', '第 1 条', 1, '政务数据管理', '数据治理岗负责数据目录编制、质量核查与共享交换的日常管理。本条与上位规定不一致的，适用上位规定。');
