INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_564058_1', 'stat_dept_564058', '第 1 条', 1, '公务员考试考', '考区应在考前完成考点勘验，考场设置须满足间距、监控和无线屏蔽要求。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_564058_2', 'stat_dept_564058', '第 2 条', 2, '公务员考试考', '试卷押运实行双人双锁，全程录像并留存不少于六个月。违反本条规定的，由主管部门责令改正并通报。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_564058_3', 'stat_dept_564058', '第 3 条', 3, '公务员考试考', '监考人员实行考前随机抽签分配，与考生有回避关系的不得参与本考区工作。');
