INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_584906_1', 'stat_dept_584906', '第 1 条', 1, '人事考试信息', '岗位表、成绩、入围线和拟录用名单应当在官方网站公开，公开期限不少于五个工作日。本条与上位规定不一致的，适用上位规定。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_584906_2', 'stat_dept_584906', '第 2 条', 2, '人事考试信息', '涉及考生个人信息的部分应作脱敏处理，仅公开姓名部分字符与准考证号后四位。具体经办科室及联系方式见南江区官网公示栏。');
