INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_259787_1', 'stat_dept_259787', '第 1 条', 1, '人事考试信息', '岗位表、成绩、入围线和拟录用名单应当在官方网站公开，公开期限不少于五个工作日。违反本条规定的，由主管部门责令改正并通报。');
