INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_025796_1', 'stat_dept_025796', '第 1 条', 1, '招录单位专业', '招录单位应指定专人负责专业认定，认定过程和结论应当留痕。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_025796_2', 'stat_dept_025796', '第 2 条', 2, '招录单位专业', '对同一专业名称的认定口径在同一年度内应保持一致，不得因人而异。本条由南岭省公务员局考试录用处负责解释。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_025796_3', 'stat_dept_025796', '第 3 条', 3, '招录单位专业', '考生提出书面咨询的，招录单位应在 3 个工作日内书面答复。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_417422_1', 'stat_dept_417422', '第 1 条', 1, '招录单位专业', '招录单位应指定专人负责专业认定，认定过程和结论应当留痕。本条由南岭省招录主管部门负责解释。');
