INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_585381_1', 'stat_dept_585381', '第 1 条', 1, '考试收费管理', '笔试考务费按物价部门核定标准收取，不得以任何名义加收。');
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES ('art_stat_dept_585381_2', 'stat_dept_585381', '第 2 条', 2, '考试收费管理', '享受最低生活保障的考生凭证明材料办理减免，减免申请在报名期内提交。违反本条规定的，由主管部门责令改正并通报。');
