INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2024_000', '（2024）南岭人仲02案2795 号', '放弃面试后要求恢复资格的争议', 'court_nl_admin', '劳动仲裁', '人事争议', '2024-10-28', '考生甲某与南岭省大数据发展管理局', '放弃面试后要求恢复资格的争议：涉岗位 NL-14380（数据治理岗），争议焦点为材料有效期。', '考生在确认期内未完成面试确认，期满后以家庭变故为由申请恢复资格。', '考生提交了医院证明；招录单位称期限内未收到任何书面说明，递补人选已确定。确认期限属于程序性强制要求，递补程序已启动并影响第三人权益，不宜回溯变更。', '确认期限属于程序性强制要求，递补程序已启动并影响第三人权益，不宜回溯变更。', '驳回考生请求。', '驳回', '招录,数据治理岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_001', '（2025）南岭云08行初3718 号', '补充公告缩窄专业范围后的信赖利益争议', 'court_nl_mid', '其他', '人事争议', '2025-06-27', '考生辛某与南岭省大数据发展管理局', '补充公告缩窄专业范围后的信赖利益争议：涉岗位 NL-14380（数据治理岗），争议焦点为材料有效期。', '岗位表发布时专业要求较宽，报名期间发布补充公告将范围限定为B12-03 数据治理方向，考生已完成报名缴费。', '考生主张已产生信赖利益；招录单位称补充公告在报名截止前发布并短信告知全体报名人员。补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '部分支持，退还该考生报名考务费，其余请求不予支持。', '部分支持', '招录,数据治理岗,考试诚信');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2024_002', '（2024）南岭云03行初7363 号', '使用所谓内部资料被认定违纪的处理争议', 'court_nl_mid', '合同纠纷', '人事争议', '2024-05-27', '考生丁某与云台区财政局', '使用所谓内部资料被认定违纪的处理争议：涉岗位 NL-14401（预算管理岗），争议焦点为程序告知。', '考生通过网络购买标称含未公开试题的资料，考后被举报并由考试机构调查。', '考试机构提交了购买记录与聊天记录；考生辩称资料实为公开题目汇编，自己并不知情。购买行为本身违反考试诚信要求，但现有证据不足以证明其获得了实际考题；应按情节轻重适用处理措施，不宜直接认定为作弊。', '购买行为本身违反考试诚信要求，但现有证据不足以证明其获得了实际考题；应按情节轻重适用处理措施，不宜直接认定为作弊。', '部分支持，将取消成绩变更为警告并记入诚信档案。', '部分支持', '招录,预算管理岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_003', '（2025）南岭人仲04案2457 号', '学信验证报告过期导致复审不通过的争议', 'court_nl_admin', '劳动仲裁', '行政确认', '2025-07-18', '考生辛某与南岭省人社厅', '学信验证报告过期导致复审不通过的争议：涉岗位 NL-14263（社保经办岗），争议焦点为信息安全责任。', '考生提交的在线验证报告有效期截至复审前一日，招录单位据此认定材料不完整。', '考生称系统当日故障无法重新打印，并提交了故障截图；招录单位称已预留补交时间。招录单位已给予补交机会而考生未在期限内补交，不予通过并无不当；但对系统故障期间的申请应予适当宽限。', '招录单位已给予补交机会而考生未在期限内补交，不予通过并无不当；但对系统故障期间的申请应予适当宽限。', '驳回考生请求，同时建议考试机构完善故障期间的补办指引。', '驳回', '招录,社保经办岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2024_004', '（2024）南岭云02行初5641 号', '代为提交敏感材料引发的信息泄露争议', 'court_nl_yuntai', '其他', '招录资格争议', '2024-05-17', '考生丙某与南岭省大数据发展管理局', '代为提交敏感材料引发的信息泄露争议：涉岗位 NL-14380（数据治理岗），争议焦点为材料有效期。', '考生委托他人代为上传身份证与成绩单，材料在传输过程中被第三方获取。', '考生主张平台安全措施不足；平台方称已提示须本人操作且不得通过非官方渠道传输。平台已尽到提示义务，考生自行选择非官方渠道传输是损害发生的主要原因；平台在日志留存方面存在不足，应承担次要责任。', '平台已尽到提示义务，考生自行选择非官方渠道传输是损害发生的主要原因；平台在日志留存方面存在不足，应承担次要责任。', '部分支持，判令平台承担部分损失并完善日志与告警机制。', '部分支持', '招录,数据治理岗,个人信息');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_005', '（2025）南岭云09行初1754 号', '代为提交敏感材料引发的信息泄露争议', 'court_nl_yuntai', '其他', '招录资格争议', '2025-04-12', '考生庚某与南岭省档案馆', '代为提交敏感材料引发的信息泄露争议：涉岗位 NL-14119（文秘岗），争议焦点为材料有效期。', '考生委托他人代为上传身份证与成绩单，材料在传输过程中被第三方获取。', '考生主张平台安全措施不足；平台方称已提示须本人操作且不得通过非官方渠道传输。平台已尽到提示义务，考生自行选择非官方渠道传输是损害发生的主要原因；平台在日志留存方面存在不足，应承担次要责任。', '平台已尽到提示义务，考生自行选择非官方渠道传输是损害发生的主要原因；平台在日志留存方面存在不足，应承担次要责任。', '部分支持，判令平台承担部分损失并完善日志与告警机制。', '部分支持', '招录,文秘岗,考试诚信');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2023_006', '（2023）南岭云01行初270 号', '使用所谓内部资料被认定违纪的处理争议', 'court_nl_mid', '其他', '信息保护纠纷', '2023-10-07', '考生丙某与临溪县市场监督管理局', '使用所谓内部资料被认定违纪的处理争议：涉岗位 NL-14212（综合执法岗），争议焦点为违纪认定。', '考生通过网络购买标称含未公开试题的资料，考后被举报并由考试机构调查。', '考试机构提交了购买记录与聊天记录；考生辩称资料实为公开题目汇编，自己并不知情。购买行为本身违反考试诚信要求，但现有证据不足以证明其获得了实际考题；应按情节轻重适用处理措施，不宜直接认定为作弊。', '购买行为本身违反考试诚信要求，但现有证据不足以证明其获得了实际考题；应按情节轻重适用处理措施，不宜直接认定为作弊。', '部分支持，将取消成绩变更为警告并记入诚信档案。', '部分支持', '招录,综合执法岗,考试诚信');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_007', '（2025）南岭云02行初6582 号', '补充公告缩窄专业范围后的信赖利益争议', 'court_nl_mid', '合同纠纷', '人事争议', '2025-05-09', '考生丁某与南岭省大数据发展管理局', '补充公告缩窄专业范围后的信赖利益争议：涉岗位 NL-14380（数据治理岗），争议焦点为材料有效期。', '岗位表发布时专业要求较宽，报名期间发布补充公告将范围限定为B12-03 数据治理方向，考生已完成报名缴费。', '考生主张已产生信赖利益；招录单位称补充公告在报名截止前发布并短信告知全体报名人员。补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '部分支持，退还该考生报名考务费，其余请求不予支持。', '部分支持', '招录,数据治理岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_008', '（2025）南岭云02行初2127 号', '放弃面试后要求恢复资格的争议', 'court_nl_yuntai', '其他', '行政确认', '2025-11-22', '考生乙某与临溪县市场监督管理局', '放弃面试后要求恢复资格的争议：涉岗位 NL-14212（综合执法岗），争议焦点为专业认定。', '考生在确认期内未完成面试确认，期满后以家庭变故为由申请恢复资格。', '考生提交了医院证明；招录单位称期限内未收到任何书面说明，递补人选已确定。确认期限属于程序性强制要求，递补程序已启动并影响第三人权益，不宜回溯变更。', '确认期限属于程序性强制要求，递补程序已启动并影响第三人权益，不宜回溯变更。', '驳回考生请求。', '驳回', '招录,综合执法岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_009', '（2025）南岭人仲08案1056 号', '补充公告缩窄专业范围后的信赖利益争议', 'court_nl_admin', '劳动仲裁', '信息保护纠纷', '2025-07-21', '考生戊某与南岭市信息中心', '补充公告缩窄专业范围后的信赖利益争议：涉岗位 NL-14477（信息运维岗），争议焦点为程序告知。', '岗位表发布时专业要求较宽，报名期间发布补充公告将范围限定为B14 计算机类，考生已完成报名缴费。', '考生主张已产生信赖利益；招录单位称补充公告在报名截止前发布并短信告知全体报名人员。补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '部分支持，退还该考生报名考务费，其余请求不予支持。', '部分支持', '招录,信息运维岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2023_010', '（2023）南岭云05行初1344 号', '专业名称与目录列名不一致引发的资格争议', 'court_nl_yuntai', '其他', '招录资格争议', '2023-12-01', '考生丁某与云台区政务服务中心', '专业名称与目录列名不一致引发的资格争议：涉岗位 NL-14308（综合管理岗），争议焦点为信息安全责任。', '考生所学专业为劳动与社会保障，报考岗位要求B12 公共管理类，招录单位以专业名称未列入目录为由不予通过资格复审。', '考生主张培养方案与目录内专业高度重合；招录单位提交了本年度专业目录和内部认定记录。专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '驳回考生请求，维持不予通过资格复审的结论。', '驳回', '招录,综合管理岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_011', '（2025）南岭云06行初7270 号', '专业名称与目录列名不一致引发的资格争议', 'court_nl_yuntai', '其他', '行政确认', '2025-02-18', '考生乙某与南岭省大数据发展管理局', '专业名称与目录列名不一致引发的资格争议：涉岗位 NL-14380（数据治理岗），争议焦点为程序告知。', '考生所学专业为大数据管理与应用，报考岗位要求B12-03 数据治理方向，招录单位以专业名称未列入目录为由不予通过资格复审。', '考生主张培养方案与目录内专业高度重合；招录单位提交了本年度专业目录和内部认定记录。专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '驳回考生请求，维持不予通过资格复审的结论。', '驳回', '招录,数据治理岗,个人信息');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_012', '（2025）南岭人仲09案4817 号', '学信验证报告过期导致复审不通过的争议', 'court_nl_admin', '劳动仲裁', '人事争议', '2025-04-01', '考生丙某与南岭省档案馆', '学信验证报告过期导致复审不通过的争议：涉岗位 NL-14119（文秘岗），争议焦点为违纪认定。', '考生提交的在线验证报告有效期截至复审前一日，招录单位据此认定材料不完整。', '考生称系统当日故障无法重新打印，并提交了故障截图；招录单位称已预留补交时间。招录单位已给予补交机会而考生未在期限内补交，不予通过并无不当；但对系统故障期间的申请应予适当宽限。', '招录单位已给予补交机会而考生未在期限内补交，不予通过并无不当；但对系统故障期间的申请应予适当宽限。', '驳回考生请求，同时建议考试机构完善故障期间的补办指引。', '驳回', '招录,文秘岗,个人信息');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2024_013', '（2024）南岭云04行初3615 号', '专业名称与目录列名不一致引发的资格争议', 'court_nl_mid', '合同纠纷', '行政确认', '2024-02-06', '考生己某与云台区财政局', '专业名称与目录列名不一致引发的资格争议：涉岗位 NL-14401（预算管理岗），争议焦点为材料有效期。', '考生所学专业为数据科学与大数据技术，报考岗位要求B08 经济学类，招录单位以专业名称未列入目录为由不予通过资格复审。', '考生主张培养方案与目录内专业高度重合；招录单位提交了本年度专业目录和内部认定记录。专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '驳回考生请求，维持不予通过资格复审的结论。', '驳回', '招录,预算管理岗,专业目录');
