INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2023_032', '（2023）南岭人仲07案7874 号', '补充公告缩窄专业范围后的信赖利益争议', 'court_nl_admin', '劳动仲裁', '人事争议', '2023-02-03', '考生己某与云台区政务服务中心', '补充公告缩窄专业范围后的信赖利益争议：涉岗位 NL-14308（综合管理岗），争议焦点为违纪认定。', '岗位表发布时专业要求较宽，报名期间发布补充公告将范围限定为B12 公共管理类，考生已完成报名缴费。', '考生主张已产生信赖利益；招录单位称补充公告在报名截止前发布并短信告知全体报名人员。补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '部分支持，退还该考生报名考务费，其余请求不予支持。', '部分支持', '招录,综合管理岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_033', '（2025）南岭云07行初8122 号', '专业名称与目录列名不一致引发的资格争议', 'court_nl_yuntai', '合同纠纷', '行政确认', '2025-10-23', '考生辛某与南岭省人社厅', '专业名称与目录列名不一致引发的资格争议：涉岗位 NL-14263（社保经办岗），争议焦点为程序告知。', '考生所学专业为信息资源管理，报考岗位要求B12 公共管理类，招录单位以专业名称未列入目录为由不予通过资格复审。', '考生主张培养方案与目录内专业高度重合；招录单位提交了本年度专业目录和内部认定记录。专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '驳回考生请求，维持不予通过资格复审的结论。', '驳回', '招录,社保经办岗,面试确认');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2024_034', '（2024）南岭云09行初1471 号', '补充公告缩窄专业范围后的信赖利益争议', 'court_nl_yuntai', '其他', '行政确认', '2024-05-14', '考生甲某与南岭省大数据发展管理局', '补充公告缩窄专业范围后的信赖利益争议：涉岗位 NL-14380（数据治理岗），争议焦点为程序告知。', '岗位表发布时专业要求较宽，报名期间发布补充公告将范围限定为B12-03 数据治理方向，考生已完成报名缴费。', '考生主张已产生信赖利益；招录单位称补充公告在报名截止前发布并短信告知全体报名人员。补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '部分支持，退还该考生报名考务费，其余请求不予支持。', '部分支持', '招录,数据治理岗,考试诚信');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2024_035', '（2024）南岭人仲02案9160 号', '学信验证报告过期导致复审不通过的争议', 'court_nl_admin', '劳动仲裁', '信息保护纠纷', '2024-06-27', '考生庚某与云台区政务服务中心', '学信验证报告过期导致复审不通过的争议：涉岗位 NL-14308（综合管理岗），争议焦点为违纪认定。', '考生提交的在线验证报告有效期截至复审前一日，招录单位据此认定材料不完整。', '考生称系统当日故障无法重新打印，并提交了故障截图；招录单位称已预留补交时间。招录单位已给予补交机会而考生未在期限内补交，不予通过并无不当；但对系统故障期间的申请应予适当宽限。', '招录单位已给予补交机会而考生未在期限内补交，不予通过并无不当；但对系统故障期间的申请应予适当宽限。', '驳回考生请求，同时建议考试机构完善故障期间的补办指引。', '驳回', '招录,综合管理岗,面试确认');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_036', '（2025）南岭人仲04案6536 号', '学信验证报告过期导致复审不通过的争议', 'court_nl_admin', '劳动仲裁', '招录资格争议', '2025-05-27', '考生乙某与南岭省档案馆', '学信验证报告过期导致复审不通过的争议：涉岗位 NL-14119（文秘岗），争议焦点为专业认定。', '考生提交的在线验证报告有效期截至复审前一日，招录单位据此认定材料不完整。', '考生称系统当日故障无法重新打印，并提交了故障截图；招录单位称已预留补交时间。招录单位已给予补交机会而考生未在期限内补交，不予通过并无不当；但对系统故障期间的申请应予适当宽限。', '招录单位已给予补交机会而考生未在期限内补交，不予通过并无不当；但对系统故障期间的申请应予适当宽限。', '驳回考生请求，同时建议考试机构完善故障期间的补办指引。', '驳回', '招录,文秘岗,个人信息');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_037', '（2025）南岭人仲04案2208 号', '使用所谓内部资料被认定违纪的处理争议', 'court_nl_admin', '劳动仲裁', '行政确认', '2025-10-06', '考生乙某与南岭省大数据发展管理局', '使用所谓内部资料被认定违纪的处理争议：涉岗位 NL-14380（数据治理岗），争议焦点为信息安全责任。', '考生通过网络购买标称含未公开试题的资料，考后被举报并由考试机构调查。', '考试机构提交了购买记录与聊天记录；考生辩称资料实为公开题目汇编，自己并不知情。购买行为本身违反考试诚信要求，但现有证据不足以证明其获得了实际考题；应按情节轻重适用处理措施，不宜直接认定为作弊。', '购买行为本身违反考试诚信要求，但现有证据不足以证明其获得了实际考题；应按情节轻重适用处理措施，不宜直接认定为作弊。', '部分支持，将取消成绩变更为警告并记入诚信档案。', '部分支持', '招录,数据治理岗,面试确认');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_038', '（2025）南岭云04行初3479 号', '放弃面试后要求恢复资格的争议', 'court_nl_yuntai', '合同纠纷', '人事争议', '2025-10-02', '考生辛某与云台区政务服务中心', '放弃面试后要求恢复资格的争议：涉岗位 NL-14308（综合管理岗），争议焦点为信息安全责任。', '考生在确认期内未完成面试确认，期满后以家庭变故为由申请恢复资格。', '考生提交了医院证明；招录单位称期限内未收到任何书面说明，递补人选已确定。确认期限属于程序性强制要求，递补程序已启动并影响第三人权益，不宜回溯变更。', '确认期限属于程序性强制要求，递补程序已启动并影响第三人权益，不宜回溯变更。', '驳回考生请求。', '驳回', '招录,综合管理岗,专业目录');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_039', '（2025）南岭人仲07案9071 号', '专业名称与目录列名不一致引发的资格争议', 'court_nl_admin', '劳动仲裁', '人事争议', '2025-05-09', '考生丁某与南岭市统计局', '专业名称与目录列名不一致引发的资格争议：涉岗位 NL-14356（统计分析岗），争议焦点为材料有效期。', '考生所学专业为大数据管理与应用，报考岗位要求B22 统计学类，招录单位以专业名称未列入目录为由不予通过资格复审。', '考生主张培养方案与目录内专业高度重合；招录单位提交了本年度专业目录和内部认定记录。专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '专业认定权属于招录单位，其依据目录列名和培养方案作出的判断并无明显不当；考生在报名前未书面咨询确认，应自行承担相应风险。', '驳回考生请求，维持不予通过资格复审的结论。', '驳回', '招录,统计分析岗,面试确认');
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_040', '（2025）南岭云03行初5080 号', '代为提交敏感材料引发的信息泄露争议', 'court_nl_mid', '合同纠纷', '行政确认', '2025-08-11', '考生庚某与南岭省人社厅', '代为提交敏感材料引发的信息泄露争议：涉岗位 NL-14263（社保经办岗），争议焦点为专业认定。', '考生委托他人代为上传身份证与成绩单，材料在传输过程中被第三方获取。', '考生主张平台安全措施不足；平台方称已提示须本人操作且不得通过非官方渠道传输。平台已尽到提示义务，考生自行选择非官方渠道传输是损害发生的主要原因；平台在日志留存方面存在不足，应承担次要责任。', '平台已尽到提示义务，考生自行选择非官方渠道传输是损害发生的主要原因；平台在日志留存方面存在不足，应承担次要责任。', '部分支持，判令平台承担部分损失并完善日志与告警机制。', '部分支持', '招录,社保经办岗,资格复审');
