INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2024_043', '（2024）南岭云08行初751 号', '放弃面试后要求恢复资格的争议', 'court_nl_mid', '合同纠纷', '招录资格争议', '2024-03-18', '考生辛某与南岭省人社厅', '放弃面试后要求恢复资格的争议：涉岗位 NL-14263（社保经办岗），争议焦点为信息安全责任。', '考生在确认期内未完成面试确认，期满后以家庭变故为由申请恢复资格。', '考生提交了医院证明；招录单位称期限内未收到任何书面说明，递补人选已确定。确认期限属于程序性强制要求，递补程序已启动并影响第三人权益，不宜回溯变更。', '确认期限属于程序性强制要求，递补程序已启动并影响第三人权益，不宜回溯变更。', '驳回考生请求。', '驳回', '招录,社保经办岗,资格复审');
