INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2025_045', '（2025）南岭人仲08案9127 号', '补充公告缩窄专业范围后的信赖利益争议', 'court_nl_admin', '劳动仲裁', '行政确认', '2025-10-26', '考生丁某与南岭市统计局', '补充公告缩窄专业范围后的信赖利益争议：涉岗位 NL-14356（统计分析岗），争议焦点为程序告知。', '岗位表发布时专业要求较宽，报名期间发布补充公告将范围限定为B22 统计学类，考生已完成报名缴费。', '考生主张已产生信赖利益；招录单位称补充公告在报名截止前发布并短信告知全体报名人员。补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '补充公告在报名截止前发布并履行了告知义务，考生有机会改报，未构成对信赖利益的不当损害。', '部分支持，退还该考生报名考务费，其余请求不予支持。', '部分支持', '招录,统计分析岗,个人信息');
