INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES ('case_nl_2024_049', '（2024）南岭云09行初8950 号', '使用所谓内部资料被认定违纪的处理争议', 'court_nl_mid', '其他', '招录资格争议', '2024-12-12', '考生丁某与南岭省档案馆', '使用所谓内部资料被认定违纪的处理争议：涉岗位 NL-14119（文秘岗），争议焦点为专业认定。', '考生通过网络购买标称含未公开试题的资料，考后被举报并由考试机构调查。', '考试机构提交了购买记录与聊天记录；考生辩称资料实为公开题目汇编，自己并不知情。购买行为本身违反考试诚信要求，但现有证据不足以证明其获得了实际考题；应按情节轻重适用处理措施，不宜直接认定为作弊。', '购买行为本身违反考试诚信要求，但现有证据不足以证明其获得了实际考题；应按情节轻重适用处理措施，不宜直接认定为作弊。', '部分支持，将取消成绩变更为警告并记入诚信档案。', '部分支持', '招录,文秘岗,资格复审');
